create table if not exists public.payments (id uuid primary key default gen_random_uuid(), reference text not null, customer_name text not null, amount numeric(12,2) not null check(amount>=0), due_date date, status text not null default 'Pending', notes text, created_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), title text not null, body text, category text not null default 'general', is_read boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.crm_settings (key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now(), updated_by uuid references auth.users(id));
create table if not exists public.website_content (id uuid primary key default gen_random_uuid(), page_key text not null, title text not null, content text, status text not null default 'Draft', updated_by uuid references auth.users(id), updated_at timestamptz not null default now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['payments','notifications','crm_settings','website_content'] LOOP EXECUTE format('alter table public.%I enable row level security',t); EXECUTE format('drop policy if exists %I on public.%I',t||'_staff_read',t); EXECUTE format('create policy %I on public.%I for select to authenticated using (public.is_crm_staff())',t||'_staff_read',t); EXECUTE format('drop policy if exists %I on public.%I',t||'_staff_write',t); EXECUTE format('create policy %I on public.%I for all to authenticated using (public.current_user_role() in (''admin'',''manager'',''finance'')) with check (public.current_user_role() in (''admin'',''manager'',''finance''))',t||'_staff_write',t); END LOOP; END $$;
